edits.newString:
// The execution endpoint is owner-gated. The screen intentionally does
// not retain a bearer token in React state, so resolve the current session
// token here when the caller did not supply one.
const sessionToken = authTokenRef.current ?? await getIVXAccessToken();
const response = await fetch(url, {
  method: 'GET',
  headers: {
    'Content-Type': 'application/json',
    ...(sessionToken ? { Authorization: `Bearer ${sessionToken}` } : {}),
  },
});
if (!response.ok) {
  setState((prev) => ({
    ...prev,
    polling: false,
    error: response.status === 401 || response.status === 403
      ? 'Owner session expired. Sign in again to resume live status.'
      : `status endpoint returned ${response.status}`,
    attempts: prev.attempts + 1,
  }));
  stoppedRef.current = true;
  return;
}

